const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
let JSDOM,VirtualConsole;try{({JSDOM,VirtualConsole}=require('jsdom'))}catch{}
const root=path.join(__dirname,'..');
const flush=async()=>{for(let i=0;i<6;i++)await new Promise(resolve=>setImmediate(resolve))};
test('IF reuses the complete offline narrative template with isolated sources and its own agency settings',{skip:!JSDOM},()=>{
 const f=boot({char:0,user:0,users:[{name:'真实姓名',nickname:'不能使用的网名'}],characters:[{name:'测试角色'}],messages:{},settings:{}});
 try{
  const original=f.w.eval('offlineDefaultReplyPrompt');
  const branch={settings:{userAgency:'takeover',wordCount:1300,rolePerspective:'third',userPerspective:'second'},summary:'分支内已发生的事'};
  const prompt=f.w.buildIfNarrativePrompt(f.w.eval('chars[0]'),branch,[{mine:true,text:'本分支输入'}],'本分支专有约束');
  for(const heading of original.match(/【[一二三四五六七八]、[^】]+】/g))assert.ok(prompt.includes(heading),heading);
  for(const text of ['不要把一次回复写成总结、结局或作者说明','心理必须为行动、对白或判断服务','每一轮至少推进一项','最后一个可回应的变化不替用户接完回应','分支内已发生的事','真实姓名：本分支输入','本分支专有约束','回复目标篇幅约 1300 字'])assert.ok(prompt.includes(text),text);
  assert.ok(prompt.includes(f.w.narrativeUserAgencyInstruction({userAgency:'takeover'})));
  assert.match(prompt,/不读取普通线上聊天、普通线下故事/);
  assert.doesNotMatch(prompt,/不能使用的网名|\{\{|逐段预演按附加的 HTML 注释规则输出/);
  branch.settings.userAgency='no-takeover';
  const restricted=f.w.buildIfNarrativePrompt(f.w.eval('chars[0]'),branch,[],'');
  assert.ok(restricted.includes(f.w.narrativeUserAgencyInstruction({userAgency:'no-takeover'})));
  assert.doesNotMatch(restricted,/抢话（当前已开启，优先于提示词中的一般用户描写限制）/);
  assert.equal(f.w.eval('offlineDefaultReplyPrompt'),original);
  assert.deepEqual(f.errors,[]);
 }finally{f.w.close()}
});
function boot(saved,fetcher){
 const errors=[],snapshots=[],html=fs.readFileSync(path.join(root,'index.html'),'utf8').replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,''),console=new VirtualConsole();
 const dom=new JSDOM(html,{runScripts:'dangerously',url:'http://localhost/',pretendToBeVisual:true,virtualConsole:console,beforeParse(w){
  w.IRIS_BOOT_STATE=saved;w.IRIS_STYLES_READY=Promise.resolve();w.fetch=async(url,...args)=>String(url).startsWith('assets/earth-cities.json')?{ok:true,json:async()=>JSON.parse(fs.readFileSync(path.join(root,'assets/earth-cities.json'),'utf8'))}:(fetcher||async function(){throw Error('no external network in local integration test')})(url,...args);w.matchMedia=()=>({matches:false,addEventListener(){},removeEventListener(){}});w.confirm=()=>true;w.scrollTo=()=>{};
  w.HTMLDialogElement.prototype.showModal=function(){this.open=true};w.HTMLDialogElement.prototype.close=function(){this.open=false;this.dispatchEvent(new w.Event('close'))};
  w.IrisStorage={mode:'test',save:async value=>snapshots.push(JSON.parse(JSON.stringify(value)))};
  w.addEventListener('error',event=>errors.push(event.error?.stack||event.message));
 }});
 const scripts=JSON.parse(fs.readFileSync(path.join(root,'scripts/storage-bootstrap.js'),'utf8').match(/const scripts = (\[[^\n]+\]);/)[1].replace(/'/g,'"'));
 for(const file of scripts){const tag=dom.window.document.createElement('script');Object.defineProperty(tag,'src',{value:'http://localhost/'+file});tag.textContent=fs.readFileSync(path.join(root,file),'utf8');dom.window.document.body.append(tag)}
 return{dom,w:dom.window,errors,snapshots};
}
test('actual Iris entry, role switching, persisted reopening and backup picker integrate without runtime errors',{skip:!JSDOM},async()=>{
 const f=boot({char:0,user:0,users:[{name:'测试用户'}],characters:[{name:'测试角色甲'},{name:'测试角色乙'}],messages:{},settings:{}});let reopened;
 try{
  assert.deepEqual(f.errors,[]);
  f.w.eval("state.characters[0].lifeTimeline=IrisTimeline.upsert(IrisTimeline.read(state.characters[0]),{title:'初始经历',description:'原始内容',type:'其他',status:'confirmed'})");
  const button=f.w.document.querySelector('[data-dock-feature="experiences"]');assert.ok(button);button.click();await flush();assert.equal(f.w.document.querySelector('.feature-page-wordmark').textContent,'Experiences');assert.ok(f.w.document.querySelector('.life-timeline'));
  f.w.document.querySelector('[data-timeline-edit]').click();const form=f.w.document.querySelector('.timeline-editor');form.querySelector('[name="title"]').value='启动后的真实记录';form.dispatchEvent(new f.w.Event('submit',{bubbles:true,cancelable:true}));await flush();assert.match(f.w.document.querySelector('.timeline-list').textContent,/启动后的真实记录/);
  const before=f.w.eval('state.characters[0].lifeTimeline.ownerId');f.w.eval('state.char=1;render()');await flush();assert.doesNotMatch(f.w.document.querySelector('.timeline-list').textContent,/启动后的真实记录/);assert.equal(f.w.document.querySelector('[data-timeline-role]').selectedOptions[0].textContent,'测试角色乙');
  f.w.closeFeaturePage();f.w.openSettings();f.w.eval("systemSettingsTab='storage';refreshSettings()");assert.ok(f.w.document.querySelector('[data-backup-category="lifeTimeline"]'));
  assert.deepEqual(f.errors,[]);
  const snapshot=f.snapshots.findLast(value=>value.characters[0].lifeTimeline?.entries.length);assert.ok(snapshot);reopened=boot(snapshot);reopened.w.openFeaturePage('experiences');await flush();assert.equal(reopened.w.eval('state.characters[0].lifeTimeline.ownerId'),before);assert.match(reopened.w.document.querySelector('.timeline-list').textContent,/启动后的真实记录/);assert.deepEqual(reopened.errors,[]);
 }finally{f.dom.window.close();reopened?.dom.window.close()}
});
